package com.medcore.backend.api.enfermeria;
import com.medcore.backend.api.internaciones.*;import com.medcore.backend.api.usuarios.*;import org.springframework.data.domain.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ObservacionService{private final ObservacionRepository repository;private final InternacionRepository internaciones;private final UsuarioRepository usuarios;public ObservacionService(ObservacionRepository repository,InternacionRepository internaciones,UsuarioRepository usuarios){this.repository=repository;this.internaciones=internaciones;this.usuarios=usuarios;}@Transactional public ObservacionResponse crear(Long internacionId,ObservacionRequest r){Internacion i=internaciones.findById(internacionId).orElseThrow(() -> new RuntimeException("Internación no encontrada: "+internacionId));if(i.getEstado()!=EstadoInternacion.ACTIVA)throw new RuntimeException("Solo se puede observar una internación activa");String username=SecurityContextHolder.getContext().getAuthentication().getName();Usuario u=usuarios.findByUsername(username).orElseThrow(() -> new UsuarioExceptions.UsuarioNoEncontradoException(username));if(u.getProfesionalId()==null)throw new RuntimeException("El usuario de enfermería no tiene profesional asociado");Observacion o=new Observacion();o.setInternacionId(internacionId);o.setEnfermeroId(u.getProfesionalId());o.setDescripcion(r.descripcion().trim());o.setTipo(r.tipo());o.setAutor(username);return ObservacionResponse.from(repository.save(o));}@Transactional(readOnly=true)public Page<ObservacionResponse> listar(Long internacionId,Pageable p){return repository.findByInternacionId(internacionId,p).map(ObservacionResponse::from);}}
